def _b(ords, o):
    return bisect.bisect_right(ords, o) - 1

def lunar_of(y, m, d):
    """返回 (农历年, 农历月, 农历日, 是否闰月)。"""
    o = datetime.date(y, m, d).toordinal()
    i = _b(LUNAR_ORDS, o)
    ly, lm, leap = LUNAR_DATA[i]
    return (ly, lm, o - LUNAR_ORDS[i] + 1, leap)

def month_gz_of(y, m, d):
    """节气月干支（立春换月口径）。"""
    o = datetime.date(y, m, d).toordinal()
    return SIXTY[MGZ_IDX[_b(MGZ_ORDS, o)]]

def year_zhi_of(y, m, d):
    """立春界年干支的地支（黄历岁破/三煞用）。"""
    o = datetime.date(y, m, d).toordinal()
    return SIXTY[YGZ_IDX[_b(YGZ_ORDS, o)]][1]

def jieqi_on(y, m, d):
    """若当日为节气，返回 (节气名, idx)，否则 None。"""
    o = datetime.date(y, m, d).toordinal()
    i = bisect.bisect_left(JIEQI_ORDS, o)
    if i < len(JIEQI_ORDS) and JIEQI_ORDS[i] == o:
        return (JQ[JIEQI_IDX[i]], JIEQI_IDX[i])
    return None

def next_liminal(y, m, d):
    """返回 (离日/决日, 节气名, 明日date) 或 None。"""
    nxt = datetime.date(y, m, d) + datetime.timedelta(days=1)
    o = nxt.toordinal()
    i = bisect.bisect_left(JIEQI_ORDS, o)
    if i < len(JIEQI_ORDS) and JIEQI_ORDS[i] == o:
        idx = JIEQI_IDX[i]
        if idx in LI_IDX:
            return ("离日", LI_IDX[idx], nxt)
        if idx in JUE_IDX:
            return ("决日", JUE_IDX[idx], nxt)
    return None